import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-125: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short125', durationInSeconds: 27.4, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short125: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(24.0);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'PRO COSTS 4X' }, { text: 'THE NEW ONE', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.2)}>
        <CoverImage src="projects/short-125/cover.png" out={secToFrame(3.2) - 10} />
        <HookTitle hold onDark kicker="GOOGLE IMAGE AI" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(7.9)}>
        <ToolCard name="Nano Banana Pro" tagline="Image output." chip="$120" at={secToFrame(3.2) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="per 1M image tokens" v="$120.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(11.7)}>
        <ToolCard name="One 1K image" tagline="On Pro." chip="13.4¢" at={secToFrame(7.9) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="per 1K image" v="$0.134" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(15.2)}>
        <ToolCard name="Nano Banana 2.1" tagline="Image output." chip="$30" at={secToFrame(11.7) - 2}>
          <Panel>
            <Line k="per 1M image tokens" v="$30.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(19.0)}>
        <ToolCard name="Same 1K image" tagline="On 2.1." chip="3.4¢" at={secToFrame(15.2) - 2}>
          <Panel>
            <Line k="per 1K image" v="$0.0336" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="4x cheaper" tagline="Same size image." chip="4X" at={secToFrame(19.0) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Pro 1K" v="$0.134" bad />
            <Line k="2.1 1K" v="$0.0336" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-125/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GOOGLE IMAGE AI" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Four times the price. Same size.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short125;
